package equivalent;

import metadata.BehavioralDifference;
import metadata.DifferenceType;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;

class ClonePair9404DifferenceFindingTest {

    private final ClonePair9404 subject = new ClonePair9404();

    /**
     * Generated by Claude Code (Claude Fable 5.1).
     * Difference type: return_value.
     * Difference manifestation: the methods return different values.
     */
    @Test
    @BehavioralDifference(DifferenceType.RETURN_VALUE)
    void methodsDisagreeOnTransposedAdjacentCharacters() {
        // method1 counts a transposition of two adjacent characters as a single edit,
        // whereas method2 computes the plain Levenshtein distance and needs two edits.
        assertEquals(1, subject.method1("ab", "ba"));
        assertEquals(2, subject.method2("ab", "ba"));
    }
}
